import { esc, header, icon } from '../components/ui.js';
import { SOURCE_LAYERS, coveragePoints, filterCoverage } from '../core/coverage.js';
export const SOURCES_PAGE_SIZE = 30;
export function sourcesPage(state, view) {
    const points = state.catalog ? coveragePoints(state.catalog) : [], filtered = filterCoverage(points, view.filter);
    const selected = filtered.find(p => p.id === view.selectedId), pages = Math.ceil(filtered.length / SOURCES_PAGE_SIZE);
    const page = Math.min(view.page, Math.max(0, pages - 1)), rows = filtered.slice(page * SOURCES_PAGE_SIZE, (page + 1) * SOURCES_PAGE_SIZE);
    return `${header(true)}<main class="page-width sources-page" id="main"><div class="sources-title"><div><span class="eyebrow">Danmark · datakilder</span><h1>Et samlet kort over vores kilder</h1><p>Se kendte placeringer, udforsk datagrundlaget og find steder med lydreferencer.</p></div><button class="btn btn-secondary" data-action="import-catalog">${icon('upload')}Importér katalog / referencer</button></div>
  <div class="coverage-controls panel" id="coverage-controls"><fieldset><legend>Vis datakilder</legend><div class="coverage-layers">${SOURCE_LAYERS.map(layer => `<label class="coverage-layer"><input type="checkbox" data-source-kind="${layer.id}" ${view.filter.kinds.includes(layer.id) ? 'checked' : ''}><i style="--source-color:${layer.color}"></i><span>${layer.label}</span><strong>${points.filter(p => p.kind === layer.id).length}</strong></label>`).join('')}</div></fieldset>
  <div class="coverage-search"><label class="field"><span>Søg på navn eller kilde-id</span><input name="coverage-query" type="search" value="${esc(view.filter.query)}" placeholder="Fx Roskilde, Billund eller Østerild" maxlength="160"></label><label class="checkbox-field"><input type="checkbox" name="coverage-references" ${view.filter.referencesOnly ? 'checked' : ''}><span>Kun steder med lydreferencer</span></label><button class="text-button" type="button" data-coverage-reset>Nulstil filtre</button></div></div>
  ${state.catalogError ? `<div class="error-box" role="alert"><div><p>${esc(state.catalogError)}</p><button class="text-button" data-action="retry-catalog">Prøv igen</button></div></div>` : ''}
  <div class="coverage-status" role="status"><strong>${filtered.length} af ${points.length} kilder vises</strong><span>Hvid ring = indlæst lydreference · tal = flere kilder</span></div>
  <div class="coverage-workspace"><div class="coverage-map" id="coverage-map"></div><aside class="coverage-sidebar" aria-label="Datakilder og detaljer">
  ${selected ? `<section class="coverage-detail"><span class="pill">${SOURCE_LAYERS.find(l => l.id === selected.kind).label}</span><h2 data-i18n-skip>${esc(selected.name)}</h2><p class="mono">${selected.lat.toFixed(5)}, ${selected.lon.toFixed(5)}</p><p>${selected.referenceCount ? `${selected.referenceCount} indlæste lydreferencer` : 'Kun geografisk placering · ingen lydreference'}</p>${selected.kind === 'airport' ? '<p>En flyplads er ikke en flybane. Historisk flydækning afhænger af tidspunktet og ADS-B-arkivet.</p>' : ''}<a class="text-link" href="${esc(selected.url)}" target="_blank" rel="noopener noreferrer">Åbn original datakilde ${icon('diagonal')}</a><p class="small-print" data-i18n-skip>${esc(selected.provenance)}<br>${esc(selected.license)}</p></section>` : '<div class="coverage-detail"><h2>Udforsk datakilderne</h2><p>Klik på en markør eller vælg en kilde i listen. Klik på en gruppe for at zoome ind.</p></div>'}
  <div class="coverage-list" aria-label="Filtrerede datakilder">${rows.map(p => `<button type="button" class="coverage-row ${p.id === view.selectedId ? 'selected' : ''}" aria-pressed="${p.id === view.selectedId}" data-source-id="${esc(p.id)}"><i style="--source-color:${SOURCE_LAYERS.find(l => l.id === p.kind).color}"></i><span><strong data-i18n-skip>${esc(p.name)}</strong><small>${p.referenceCount ? 'Lydreference indlæst' : 'Geografisk placering'}</small></span>${icon('chevron')}</button>`).join('') || `<p class="coverage-empty">${state.catalog ? 'Ingen kilder matcher filtrene. Prøv en anden søgning eller slå flere lag til.' : state.catalogError ? 'Kataloget er ikke tilgængeligt.' : 'Indlæser datakilder …'}</p>`}</div>
  ${pages > 1 ? `<div class="coverage-pagination"><button class="text-button" data-coverage-page="${page - 1}" ${page === 0 ? 'disabled' : ''}>Forrige</button><span>${page + 1} / ${pages}</span><button class="text-button" data-coverage-page="${page + 1}" ${page >= pages - 1 ? 'disabled' : ''}>Næste</button></div>` : ''}</aside></div>
  <div class="coverage-notes panel"><h2>Hvad viser kortet?</h2><p>Markører er kendte kildeplaceringer, ikke områder med garanteret lyd- eller flydækning. Kirker på kortet er ikke verificerede aktive klokkekilder. Vindmølleparker vises som parkpositioner, hvor individuelle møllepositioner mangler.</p><p>Kun ikke-syntetiske lydreferencer i den aktuelle session tælles. Referencerne følger med, når du importerer dem eller opretter dem i analyselaboratoriet.</p>${state.catalog ? `<p class="small-print">${esc(state.catalog.coverage)}</p><p class="source-credit" data-i18n-skip>${esc(state.catalog.source)} · ${esc(state.catalog.license)}</p>` : ''}<a class="text-link" href="#/lab">Åbn analyselaboratoriet ${icon('arrow')}</a></div></main>`;
}
